document.querySelectorAll("form[data-confirm]").forEach(e=>{e.addEventListener("submit",t=>{window.confirm(e.dataset.confirm||"Lanjutkan tindakan ini?")||t.preventDefault()})});const e=document.querySelector("[data-slug-source]"),t=document.querySelector("[data-slug-target]");if(e&&t){let r=""!==t.value.trim();const a=e=>e.normalize("NFKD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"").slice(0,160);t.addEventListener("input",()=>{r=""!==t.value.trim()}),e.addEventListener("input",()=>{r||(t.value=a(e.value))})}const r=document.querySelector("[data-form-errors]");r&&r.focus({preventScroll:!1});
